-- Phase 2 persistent database. V1 intentionally uses browser storage.
create table if not exists model_trades(id uuid primary key default gen_random_uuid(),ticker text not null,trade_date date,buy_price numeric,target numeric,stop_loss numeric,position_pct numeric,model_exit_price numeric,model_booked_pct numeric,status text default 'booked',notes text,created_at timestamptz default now());
create table if not exists actual_trades(id uuid primary key default gen_random_uuid(),ticker text not null,buy_date date,qty numeric not null,buy_price numeric not null,sell_qty numeric,sell_price numeric,sell_qty_2 numeric,sell_price_2 numeric,status text default 'booked',reason text,brokerage numeric default 0,stt numeric default 0,exchange_charges numeric default 0,sebi_charges numeric default 0,gst numeric default 0,stamp_duty numeric default 0,dp_charges numeric default 0,other_charges numeric default 0,notes text,created_at timestamptz default now());
